\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE calc_assertions(n INT PRIMARY KEY,name TEXT,passed BOOLEAN,detail TEXT);
CREATE OR REPLACE FUNCTION pg_temp.ok(n INT,name TEXT,passed BOOLEAN,detail TEXT DEFAULT NULL) RETURNS VOID LANGUAGE plpgsql AS $$BEGIN INSERT INTO calc_assertions VALUES(n,name,COALESCE(passed,FALSE),detail);IF passed THEN RAISE NOTICE 'PASS %: %',n,name;ELSE RAISE NOTICE 'FAIL %: % (%)',n,name,detail;END IF;END$$;

