CREATE OR REPLACE FUNCTION pg_temp.add_item(order_id UUID,test_code TEXT,item_id UUID,bill_item_id UUID) RETURNS VOID LANGUAGE plpgsql AS $$DECLARE t public.tests%ROWTYPE;bill UUID;BEGIN
 SELECT * INTO t FROM public.tests WHERE code=test_code;SELECT o.bill_id INTO bill FROM public.clinical_orders o WHERE o.id=order_id;
 INSERT INTO public.bill_items(id,bill_id,test_id,test_code_snapshot,test_name_snapshot,reporting_type,unit_price_paisa,net_price_paisa) VALUES(bill_item_id,bill,t.id,t.code,t.name,t.reporting_type,0,0);
 INSERT INTO public.clinical_order_items(id,order_id,bill_item_id,test_id,test_name,department,reporting_type,specimen_type,container_type,status,workflow_type,clinical_reporting_enabled,collection_required,result_revision)
 VALUES(item_id,order_id,bill_item_id,t.id,t.name,t.department,t.reporting_type,COALESCE(t.sample_type,''),COALESCE(t.container,''),'ResultDrafted',t.workflow_type,TRUE,FALSE,1);
 INSERT INTO public.test_results(order_item_id,parameter_id,parameter_name,unit,value_type,display_value,status)
 SELECT item_id,p.id,p.name,p.unit,p.value_type,CASE WHEN p.value_type='Calculated' THEN 'Pending calculation' ELSE '' END,'Draft' FROM public.parameters p WHERE p.test_id=t.id AND p.is_active AND p.lifecycle_status='Active';
END$$;
CREATE OR REPLACE FUNCTION pg_temp.setval(p_item UUID,p_code TEXT,p_value NUMERIC) RETURNS VOID LANGUAGE sql AS $$UPDATE public.test_results tr SET numeric_value=p_value,display_value=p_value::TEXT FROM public.parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id=p_item AND p.code=p_code$$;
CREATE OR REPLACE FUNCTION pg_temp.val(p_item UUID,p_code TEXT) RETURNS NUMERIC LANGUAGE sql AS $$SELECT tr.numeric_value FROM public.test_results tr JOIN public.parameters p ON p.id=tr.parameter_id WHERE tr.order_item_id=p_item AND p.code=p_code$$;

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','TLC','99400000-0000-0000-0000-000000000001','99500000-0000-0000-0000-000000000001');
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','DLC','99400000-0000-0000-0000-000000000002','99500000-0000-0000-0000-000000000002');
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','ABS_DLC','99400000-0000-0000-0000-000000000003','99500000-0000-0000-0000-000000000003');
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000001','TLC_VAL',8000);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000002','NEUT_VAL',60);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000002','LYMPH_VAL',30);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000002','MONO_VAL',4);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000002','EOSIN_VAL',5);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000002','BASO_VAL',1);
SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000003');
SELECT pg_temp.ok(1,'ABS_DLC complete computes five',pg_temp.val('99400000-0000-0000-0000-000000000003','ANC')=4800 AND pg_temp.val('99400000-0000-0000-0000-000000000003','ALC')=2400 AND pg_temp.val('99400000-0000-0000-0000-000000000003','AMC')=320 AND pg_temp.val('99400000-0000-0000-0000-000000000003','AEC')=400 AND pg_temp.val('99400000-0000-0000-0000-000000000003','ABC')=80);
UPDATE public.test_results tr SET numeric_value=NULL,display_value='' FROM public.parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id='99400000-0000-0000-0000-000000000001' AND p.code='TLC_VAL';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000003');
SELECT pg_temp.ok(2,'ABS_DLC missing TLC blocked',pg_temp.val('99400000-0000-0000-0000-000000000003','ANC') IS NULL AND EXISTS(SELECT 1 FROM clinical_calculation_runs r WHERE r.order_item_id='99400000-0000-0000-0000-000000000003' AND r.calculation_status='MissingInput'));
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000001','TLC_VAL',8000);UPDATE public.test_results tr SET numeric_value=NULL,display_value='' FROM public.parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id='99400000-0000-0000-0000-000000000002' AND p.code='EOSIN_VAL';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000003');
SELECT pg_temp.ok(3,'one missing differential only blocks applicable output',pg_temp.val('99400000-0000-0000-0000-000000000003','AEC') IS NULL AND pg_temp.val('99400000-0000-0000-0000-000000000003','ANC')=4800);
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000004','TLC','99400000-0000-0000-0000-000000000004','99500000-0000-0000-0000-000000000004');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000004','TLC_VAL',9999);
UPDATE public.test_results tr SET numeric_value=NULL,display_value='' FROM public.parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id='99400000-0000-0000-0000-000000000001' AND p.code='TLC_VAL';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000003');SELECT pg_temp.ok(4,'ABS_DLC cannot use previous order TLC',pg_temp.val('99400000-0000-0000-0000-000000000003','ANC') IS NULL);

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','CREATININE','99400000-0000-0000-0000-000000000005','99500000-0000-0000-0000-000000000005');SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','EGFR','99400000-0000-0000-0000-000000000006','99500000-0000-0000-0000-000000000006');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000005','CREAT_VAL',1);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000006');SELECT pg_temp.ok(5,'eGFR valid demographics computed',pg_temp.val('99400000-0000-0000-0000-000000000006','EGFR_RESULT') IS NOT NULL);
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000002','CREATININE','99400000-0000-0000-0000-000000000007','99500000-0000-0000-0000-000000000007');SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000002','EGFR','99400000-0000-0000-0000-000000000008','99500000-0000-0000-0000-000000000008');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000007','CREAT_VAL',1);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000008');SELECT pg_temp.ok(6,'eGFR missing age blocked',pg_temp.val('99400000-0000-0000-0000-000000000008','EGFR_RESULT') IS NULL);
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000003','CREATININE','99400000-0000-0000-0000-000000000009','99500000-0000-0000-0000-000000000009');SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000003','EGFR','99400000-0000-0000-0000-000000000010','99500000-0000-0000-0000-000000000010');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000009','CREAT_VAL',1);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000010');SELECT pg_temp.ok(7,'eGFR unsupported sex blocked',pg_temp.val('99400000-0000-0000-0000-000000000010','EGFR_RESULT') IS NULL);
SELECT pg_temp.ok(8,'eGFR demographic authority is server-side',EXISTS(SELECT 1 FROM clinical_calculation_formula_inputs i JOIN clinical_calculation_formula_versions f ON f.id=i.formula_version_id WHERE f.formula_identifier='EGFR_CKD_EPI_2021_V1' AND i.source_type='PATIENT_DEMOGRAPHIC' AND i.source_identifier='AGE_YEARS'));

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','BILIRUBIN_TD','99400000-0000-0000-0000-000000000011','99500000-0000-0000-0000-000000000011');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000011','TOTAL_BILIRUBIN',1.2);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000011','DIRECT_BILIRUBIN',0.3);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000011');SELECT pg_temp.ok(9,'indirect bilirubin computed',pg_temp.val('99400000-0000-0000-0000-000000000011','INDIRECT_BILIRUBIN')=.9);
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000011','DIRECT_BILIRUBIN',2);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000011');SELECT pg_temp.ok(10,'direct above total blocked',pg_temp.val('99400000-0000-0000-0000-000000000011','INDIRECT_BILIRUBIN') IS NULL);

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','LFT','99400000-0000-0000-0000-000000000012','99500000-0000-0000-0000-000000000012');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000012','TP',7);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000012','ALB',4);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000012','TBIL',1);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000012','DBIL',.2);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000012');SELECT pg_temp.ok(11,'LFT globulin computed',pg_temp.val('99400000-0000-0000-0000-000000000012','GLOB')=3);
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000012','TP',4);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000012');SELECT pg_temp.ok(12,'zero globulin blocks AG ratio',pg_temp.val('99400000-0000-0000-0000-000000000012','AG_RATIO') IS NULL);

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','LIPID_PROFILE','99400000-0000-0000-0000-000000000013','99500000-0000-0000-0000-000000000013');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000013','CHOL',200);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000013','TRIG',150);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000013','HDL',50);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000013');SELECT pg_temp.ok(13,'lipid profile derived values computed',pg_temp.val('99400000-0000-0000-0000-000000000013','VLDL')=30 AND pg_temp.val('99400000-0000-0000-0000-000000000013','TC_HDL_RATIO')=4 AND pg_temp.val('99400000-0000-0000-0000-000000000013','NON_HDL')=150);
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000013','HDL',0);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000013');SELECT pg_temp.ok(14,'zero HDL blocks ratio',pg_temp.val('99400000-0000-0000-0000-000000000013','TC_HDL_RATIO') IS NULL);
SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','CHOL_TOTAL','99400000-0000-0000-0000-000000000014','99500000-0000-0000-0000-000000000014');SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000014');SELECT pg_temp.ok(15,'standalone cholesterol triggers no profile formula',NOT EXISTS(SELECT 1 FROM clinical_calculation_runs WHERE order_item_id='99400000-0000-0000-0000-000000000014'));

SELECT pg_temp.add_item('99300000-0000-0000-0000-000000000001','PT_INR','99400000-0000-0000-0000-000000000015','99500000-0000-0000-0000-000000000015');SELECT pg_temp.setval('99400000-0000-0000-0000-000000000015','PATIENT_PT',24);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000015','CONTROL_TIME',12);SELECT pg_temp.setval('99400000-0000-0000-0000-000000000015','ISI',1);SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000015');SELECT pg_temp.ok(16,'INR complete computed',pg_temp.val('99400000-0000-0000-0000-000000000015','INR')=2);
UPDATE public.test_results tr SET numeric_value=NULL,display_value='' FROM public.parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id='99400000-0000-0000-0000-000000000015' AND p.code='ISI';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000015');SELECT pg_temp.ok(17,'INR missing ISI blocked',pg_temp.val('99400000-0000-0000-0000-000000000015','INR') IS NULL);
SELECT pg_temp.ok(18,'unrelated orders execute no unrelated formulas',NOT EXISTS(SELECT 1 FROM clinical_calculation_runs r JOIN clinical_order_items oi ON oi.id=r.order_item_id WHERE oi.test_id=(SELECT id FROM tests WHERE code='CHOL_TOTAL')));
SELECT pg_temp.setval('99400000-0000-0000-0000-000000000013','HDL',40);UPDATE clinical_order_items SET result_revision=result_revision+1 WHERE id='99400000-0000-0000-0000-000000000013';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000013');SELECT pg_temp.ok(19,'dependency update recomputes',pg_temp.val('99400000-0000-0000-0000-000000000013','TC_HDL_RATIO')=5);
UPDATE clinical_order_items SET status='SignedOff' WHERE id='99400000-0000-0000-0000-000000000013';UPDATE test_results tr SET numeric_value=777,display_value='777' FROM parameters p WHERE tr.parameter_id=p.id AND tr.order_item_id='99400000-0000-0000-0000-000000000013' AND p.code='VLDL';SELECT public.run_governed_order_item_calculations('99400000-0000-0000-0000-000000000013');SELECT pg_temp.ok(20,'signed item unchanged by later calculation run',pg_temp.val('99400000-0000-0000-0000-000000000013','VLDL')=777);

SELECT count(*) passed,count(*) FILTER(WHERE NOT passed) failed FROM calc_assertions;
DO $$BEGIN IF EXISTS(SELECT 1 FROM calc_assertions WHERE NOT passed) THEN RAISE EXCEPTION 'Formula runtime failures remain';END IF;END$$;
ROLLBACK;
